package com.kfpun.japanesedaily.locale

/**
 * The UI languages, in the order of iOS `L.languageOrder` (roughly by how many people learn
 * Japanese in each), both pickers' order.
 *
 * [id] is the code stored and sent in analytics, the same as iOS (`zh` is Simplified Chinese,
 * `zh-Hant` Traditional). [localeTag] is the BCP 47 tag Android applies; it matches the
 * `values-*` folder and `res/xml/locales_config.xml`, both generated by
 * `scripts/build-android-strings.py`, which keeps its own copy of this list; [AppLanguageTest]
 * fails when they differ.
 */
enum class AppLanguage(val id: String, val localeTag: String) {
    ENGLISH("en", "en"),
    SIMPLIFIED_CHINESE("zh", "zh-Hans"),
    TRADITIONAL_CHINESE("zh-Hant", "zh-Hant"),
    INDONESIAN("id", "id"),
    KOREAN("ko", "ko"),
    VIETNAMESE("vi", "vi"),
    THAI("th", "th"),
    FILIPINO("fil", "fil"),
    BURMESE("my", "my"),
    HINDI("hi", "hi"),
    BENGALI("bn", "bn"),
    TAMIL("ta", "ta"),
    TELUGU("te", "te"),
    NEPALI("ne", "ne"),
    SPANISH("es", "es"),
    FRENCH("fr", "fr"),
    ITALIAN("it", "it"),
    GERMAN("de", "de"),
    RUSSIAN("ru", "ru");

    companion object {
        /** The language stored under [id], or null (follow the phone) for nothing or an unknown id. */
        fun fromId(id: String?): AppLanguage? = entries.firstOrNull { it.id == id }

        /**
         * The language a locale tag stands for, or null when the app has none for it. Chinese
         * follows iOS `L.deviceDefault`: Simplified only when the script or region says so
         * (`Hans`, `CN`, `SG`), otherwise Traditional. Legacy codes `in` (Indonesian) and `tl`
         * (Filipino) are accepted.
         */
        fun fromLocaleTag(tag: String?): AppLanguage? {
            if (tag.isNullOrBlank()) return null
            val parts = tag.replace('_', '-').split('-')
            val language = when (val code = parts[0].lowercase()) {
                "in" -> "id"
                "tl" -> "fil"
                else -> code
            }
            if (language == "zh") {
                val rest = parts.drop(1).map { it.lowercase() }
                val simplified = "hans" in rest || (("hant" !in rest) && rest.any { it == "cn" || it == "sg" })
                return if (simplified) SIMPLIFIED_CHINESE else TRADITIONAL_CHINESE
            }
            return entries.firstOrNull { it.localeTag == language }
        }
    }
}
